#include <stdio.h>
#define N 5

int main(void) {
    int A[N][N];            /* 对称矩阵：A[i][j] == A[j][i] */
    int sa[N*(N+1)/2];      /* 只存下三角，共 15 个元素 */
    for (int i = 0; i < N; i++)
        for (int j = 0; j <= i; j++)
            sa[i*(i+1)/2 + j] = A[i][j];   /* k = i(i+1)/2 + j */
    return 0;
}
